def execute(arguments):
    """
    复制文件或目录

    参数:
        arguments (dict): 包含以下字段
            - source (str): 源文件路径，必填
            - destination (str): 目标路径，必填

    返回:
        dict: 包含复制结果的字典
            - success (bool): 是否成功
            - source (str): 源路径
            - destination (str): 目标路径
            - size (int): 文件大小（字节）
            - error (str): 错误信息（失败时）
    """
    import os
    import shutil

    source = arguments.get("source", "")
    destination = arguments.get("destination", "")

    if not source or not destination:
        return {"success": False, "error": "请提供源路径和目标路径"}

    if not os.path.exists(source):
        return {"success": False, "error": f"源文件不存在: {source}"}

    try:
        dest_dir = os.path.dirname(destination)
        if dest_dir and not os.path.exists(dest_dir):
            os.makedirs(dest_dir, exist_ok=True)

        if os.path.isdir(source):
            shutil.copytree(source, destination)
        else:
            shutil.copy2(source, destination)

        return {
            "success": True,
            "source": source,
            "destination": destination,
            "size": os.path.getsize(destination) if os.path.isfile(destination) else None
        }
    except Exception as e:
        return {"success": False, "error": f"复制失败: {str(e)}"}
